window.__finlexDocLoaded(10032,{"id":10032,"articles":[{"id":1000077,"no":"Overview","heading":"Scope & Key Requirements (Public Summary)","text":"Deals with the auditor's responsibilities relating to accounting estimates and related disclosures in an audit of financial statements, emphasizing estimation uncertainty and inherent risk factors.","seq":0},{"id":1000078,"no":"ISA 540.13–36","heading":"Auditing Accounting Estimates: Three Testing Approaches & Bias","text":"• Separate inherent and control risk assessment considering estimation uncertainty, complexity, and subjectivity (ISA 540.16).\n• Three testing approaches (ISA 540.18): (a) obtain evidence from events occurring up to auditor's report date; (b) test how management made the estimate (method, significant assumptions, data); (c) develop an auditor's point estimate or range.\n• Stand-back evaluation (ISA 540.33–36): evaluate indicators of possible management bias and reasonableness of disclosures (converged with China CSA 1321).","seq":1},{"id":1000079,"no":"Official Access","heading":"Official Handbook & Reference Entry","text":"Official source (IAASB 2026 Handbook): https://www.iaasb.org/publications/2026-handbook-international-quality-management-auditing-review-sustainability-and-other-assurance\nStatus: in_force. Detailed paragraph-level summaries and practice notes can be expanded incrementally.\n2026 Handbook Volume: Volume 1 (ISQM 1–2, ISA 200–720)\nLocal Private Full-Text Import: Place the free official 2026 IAASB Handbook PDF in local_pdfs/ and run `python3 scripts/import_private_intl_pdfs.py`.","seq":2}]});
